bash.command:
# 022 Acceptance: full server purchase smoke
set -eo pipefail
layerfs() { node "$DSH_LAYERFS_CLI" "$@"; }
. "{{scenario}}/../shared/replay.sh"
sb=$(sandbox_of root)
ws=$(layerfs workspace mount "$sb" acceptance | field ws); echo "mounted acceptance as $ws"
code=0; layerfs workspace exec "$ws" -m '022 Acceptance: start server, purchase and read order, stop server' --stream -- 'timeout 30 node --input-type=module <<'\''SHOP_SMOKE'\''
import {spawn} from '\''node:child_process'\'';
import assert from '\''node:assert/strict'\'';
const child=spawn(process.execPath,['\''src/main.js'\''],{env:{...process.env,PORT:'\''0'\''},stdio:['\''ignore'\'','\''pipe'\'','\''pipe'\'']});
const closed=new Promise(resolve=>child.once('\''exit'\'',(code,signal)=>resolve({code,signal})));
let output='\'''\'';child.stderr.on('\''data'\'',data=>process.stderr.write(data));
const deadline=setTimeout(()=>{child.kill('\''SIGKILL'\'');},20000);
try {
 const port=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(new Error('\''Server readiness timeout'\'')),5000);child.once('\''error'\'',reject);child.once('\''exit'\'',()=>reject(new Error('\''Server exited before ready'\'')));child.stdout.on('\''data'\'',data=>{output+=data;const match=output.match(/Shop listening on (\d+)/);if(match){clearTimeout(timer);resolve(Number(match[1]));}});});
 const base='\''http://127.0.0.1:'\''+port;
 async function request(path,method='\''GET'\'',body){const response=await fetch(base+path,{method,headers:{'\''content-type'\'':'\''application/json'\''},body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(5000)});const value=await response.json();assert.ok(response.ok,JSON.stringify(value));return {status:response.status,body:value};}
 assert.deepEqual((await request('\''/health'\'')).body,{status:'\''ok'\''});
 const cart=(await request('\''/api/carts'\'','\''POST'\'')).body;
 const added=await request('\''/api/carts/'\''+cart.id+'\''/items'\'','\''POST'\'',{productId:'\''mug-classic'\'',quantity:1});assert.equal(added.body.items.length,1);
 const order=await request('\''/api/checkout'\'','\''POST'\'',{cartId:cart.id,email:'\''smoke@example.com'\''});assert.equal(order.status,201);
 assert.deepEqual((await request('\''/api/orders/'\''+order.body.id)).body,order.body);
 console.log(JSON.stringify({smoke:'\''PASS'\'',health:true,cart:cart.id,order:order.body.id,totalCents:order.body.totalCents}));
} finally {child.kill('\''SIGTERM'\'');const result=await closed;clearTimeout(deadline);console.log('\''server stopped'\'',JSON.stringify(result));}
SHOP_SMOKE' || code=$?
exit_is "$code" 0
layerfs workspace commit "$ws" -m '022 Acceptance: end-to-end server smoke (exit 0)' | kind Committed
layerfs workspace unmount "$ws" | kind Unmounted
